const CMB=q=>{if(!q.o||!q.o.every(x=>/^[ㄱ-ㅎ](, [ㄱ-ㅎ])*$/.test(x)))return q;const ans=q.o[q.a];const o=[...q.o].sort((a,b)=>a.length-b.length||(a<b?-1:a>b?1:0));q.o=o;q.a=o.indexOf(ans);return q};
const TRM=q=>{q.q=q.q.replace(/\s+$/,'');return q};Object.values(ETQ).forEach(L=>L.forEach(TRM));Object.values(ETMK).forEach(L=>L.forEach(TRM));
Object.values(ETQ).forEach(L=>L.forEach(CMB));Object.values(ETMK).forEach(L=>L.forEach(CMB));
CUR[ETN]=UN.map((n,u)=>({n,m:MN[u].map((nm,k)=>{const pre='etn'+(u+1)+(k+1);return {n:nm,q:(ETQ[u+'-'+k]||[]).map((q,i)=>Object.assign({id:pre+(q.lv?'x':'b')+String(i+1).padStart(2,'0')},q))}})}));
